-- SafetyTraining v22.002 — course-specific scenarios/labs for legacy profiles and competency verification.
-- The interim quality function created in the live migration is intentionally superseded by v22.007;
-- replaying the full migration chain reaches the same final schema/function state.

insert into public.training_scenarios_v22(stable_key,title,scenario_type,role_focus,intro,prompt,decisions,debrief,visuals,media,sources) values
('v22:backoffice-workstation','Back office: micro-audit della postazione e del flusso di lavoro','hazard_spotting','impiegato back office','La postazione sembra ordinaria, ma ergonomia, cablaggi, carico mentale, vie di esodo e organizzazione del lavoro possono sommarsi.','Osserva la postazione e individua le criticità che correggeresti prima, distinguendo problemi ergonomici, elettrici, organizzativi ed emergenziali.','[{"choice":"Riorganizzo postazione, cavi, pause e accessibilità prima che il disagio diventi esposizione cronica","effect":"Intervento preventivo e verificabile"},{"choice":"Mi limito a cambiare posizione quando sento fastidio","effect":"Correzione tardiva e non sistemica"}]'::jsonb,'{"questions":["Quale modifica puoi fare subito?","Quale problema richiede un intervento organizzativo?","Come verifichi che la soluzione funzioni dopo una settimana?"]}'::jsonb,'[{"asset":"idea-vdt-ergonomia.svg"},{"asset":"idea-emergency-steps.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - lavoro al videoterminale e rischi quotidiani","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"},{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb),
('v22:frontoffice-public','Front office: conflitto con il pubblico e sicurezza dell’ambiente','role_play','impiegato front office','Una persona al banco alza progressivamente il tono mentre altri utenti attendono e una collega è isolata in una stanza vicina.','Gestisci distanza, comunicazione, segnali di escalation, richiesta di supporto e via di uscita senza trasformare il confronto in una sfida personale.','[{"choice":"Mantengo distanza, tono calmo, confini chiari e attivo supporto secondo procedura","effect":"De-escalation con tutela dell’operatore"},{"choice":"Rispondo con lo stesso tono per ristabilire autorità","effect":"Aumento della probabilità di escalation"}]'::jsonb,'{"questions":["Quali segnali anticipano l’escalation?","Quando interrompi il servizio?","Quale assetto fisico del front office riduce il rischio?"]}'::jsonb,'[{"asset":"idea-aggression-flow.svg"},{"asset":"idea-front-layout.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - comunicazione, stress e comportamento sicuro","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"},{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb),
('v22:ecologici-route','Operatori ecologici: giro operativo, traffico, mezzi e rifiuti taglienti','hazard_spotting','operatore ecologico','Il turno inizia su strada con mezzo in movimento, visibilità variabile, cassonetti, sollevamenti e possibile presenza di taglienti.','Prima di iniziare il giro, costruisci un pre-start: mezzo, DPI, visibilità, percorso, interazioni con il traffico, movimentazione e gestione di un rifiuto pericoloso.','[{"choice":"Definisco sequenza, comunicazioni e condizioni di stop prima del primo conferimento","effect":"Riduzione dell’improvvisazione"},{"choice":"Adatto tutto sul momento perché il percorso cambia spesso","effect":"Esposizione non controllata"}]'::jsonb,'{"questions":["Come ti rendi visibile?","Che cosa fai se trovi un tagliente?","Quando una manovra del mezzo va interrotta?"]}'::jsonb,'[{"asset":"idea-road-safety.svg"},{"asset":"idea-sharps-safe.svg"},{"asset":"idea-compactor-safe.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - trasporti, movimentazione e rischi operativi","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"},{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb),
('v22:polizia-roadside','Polizia locale: intervento su strada, notte e conflitto','decision','operatore polizia locale','Un controllo stradale serale combina traffico, visibilità ridotta, contatto con il pubblico e possibile escalation verbale.','Organizza posizionamento, visibilità, zona sicura, comunicazione e supporto prima di iniziare il contatto operativo.','[{"choice":"Creo una zona di lavoro leggibile e una via di disimpegno prima del contatto","effect":"Controllo di traffico e conflitto"},{"choice":"Mi concentro solo sull’interlocutore e gestisco il traffico dopo","effect":"Perdita di consapevolezza situazionale"}]'::jsonb,'{"questions":["Dove ti posizioni?","Quale segnale ti fa chiedere supporto?","Come eviti di perdere la via di disimpegno?"]}'::jsonb,'[{"asset":"idea-police-road.svg"},{"asset":"idea-police-night.svg"},{"asset":"idea-police-conflict.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - sicurezza stradale e comportamento","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"},{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb),
('v22:verde-prestart','Verde pubblico: attrezzatura, calore, quota e area di lavoro','hazard_spotting','addetto verde','La giornata prevede attrezzature da taglio, caldo, possibile lavoro in altezza e presenza di utenti nelle vicinanze.','Prepara il lavoro scegliendo attrezzatura, protezioni, segregazione, gestione del caldo e condizioni che richiedono rinvio o stop.','[{"choice":"Separo area, controllo attrezzatura e ripianifico in base a caldo e quota","effect":"Pre-start completo"},{"choice":"Parto dall’attrezzatura disponibile e aggiusto il resto in corso d’opera","effect":"Rischi simultanei non governati"}]'::jsonb,'{"questions":["Quale rischio richiede segregazione?","Quando il caldo modifica il piano?","Che cosa cambia se serve lavorare in quota?"]}'::jsonb,'[{"asset":"idea-chainsaw-safe.svg"},{"asset":"idea-heat-stress.svg"},{"asset":"idea-working-height-safe.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - manutenzione, attrezzature e lavoro all’aperto","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"},{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb),
('v22:fondamenti-control','Fondamenti: dal pericolo alla misura più efficace','decision','lavoratore','Un pericolo è noto da tempo ma la risposta abituale è “fai attenzione”.','Ricostruisci la gerarchia delle misure: elimina, sostituisci, proteggi collettivamente, organizza, usa DPI e definisci chi deve intervenire quando il rischio supera il tuo ruolo.','[{"choice":"Cerco prima una misura che modifichi il sistema o l’ambiente","effect":"Prevenzione alla fonte"},{"choice":"Aggiungo solo un richiamo comportamentale","effect":"Il pericolo resta sostanzialmente invariato"}]'::jsonb,'{"questions":["Quale misura viene prima del DPI?","Quando devi fermarti e segnalare?","Quale figura coinvolgi per modificare l’organizzazione?"]}'::jsonb,'[{"asset":"piramide-pericoli.svg"},{"asset":"idea-safety-system.svg"},{"asset":"organigramma-sicurezza.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - principi di prevenzione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"},{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb)
on conflict (stable_key) do update set title=excluded.title,scenario_type=excluded.scenario_type,role_focus=excluded.role_focus,intro=excluded.intro,prompt=excluded.prompt,decisions=excluded.decisions,debrief=excluded.debrief,visuals=excluded.visuals,media=excluded.media,sources=excluded.sources,active=true,updated_at=now();

insert into public.practice_labs_v22(stable_key,title,lab_type,objective,briefing,steps,checklist,critical_errors,stop_conditions,media,sources,requires_physical_validation) values
('v22:backoffice-audit','Micro-audit postazione Back Office','digital','Saper trasformare disturbi quotidiani della postazione in correzioni misurabili.','Usa la tua postazione reale oppure una fotografia equivalente.','["fotografa o osserva la postazione","controlla altezza schermo/seduta e appoggi","controlla cavi e prese senza smontare nulla","verifica luce, riflessi e passaggi","analizza ritmo, pause e alternanza","scegli tre correzioni","verifica dopo una settimana"]'::jsonb,'["schermo e distanza","seduta e appoggi","illuminazione","cablaggi/passaggi","pause/alternanza","vie di esodo"]'::jsonb,'["correggere solo la postura ignorando l’organizzazione","usare adattatori elettrici impropri","ostruire percorsi con cavi o materiali"]'::jsonb,'["guasto elettrico o surriscaldamento","dolore importante o sintomi persistenti da riferire secondo procedura","via di esodo ostruita"]'::jsonb,'[{"kind":"video_hub","title":"Napo - rischi in ufficio","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:frontoffice-deescalation','Role-play Front Office: de-escalation e richiesta supporto','hybrid','Allenare comunicazione, distanza, confini e attivazione del supporto.','Due persone simulano operatore e utente; una terza osserva con checklist.','["predisponi posizione e via di uscita","ascolta e riassumi la richiesta","usa tono e frasi non provocatorie","mantieni distanza e confini","riconosci segnali di escalation","attiva supporto o interrompi il contatto","debriefing tra i partecipanti"]'::jsonb,'["distanza","tono","chiarezza","via di fuga","attivazione supporto","chiusura sicura"]'::jsonb,'["avvicinarsi per imporre controllo","bloccare fisicamente l’uscita","discutere sul piano personale","continuare quando la minaccia cresce"]'::jsonb,'["minaccia concreta","arma o oggetto potenzialmente offensivo","impossibilità di mantenere distanza/uscita"]'::jsonb,'[{"kind":"video_hub","title":"Napo - stress e comunicazione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:ecologici-prestart','Pre-start operativo rifiuti e raccolta','hybrid','Allenare la lettura congiunta di mezzo, traffico, rifiuto, movimentazione e visibilità.','Applicare la checklist a un mezzo reale fermo oppure a una simulazione fotografica.','["controllo mezzo e dispositivi visivi","verifica DPI e comunicazioni","leggi percorso e punti critici","simula una manovra con zona segregata","gestisci un tagliente simulato senza contatto","valuta un carico ingombrante","debriefing su quasi incidente"]'::jsonb,'["mezzo","alta visibilità","zona manovra","taglienti","movimentazione","comunicazione"]'::jsonb,'["entrare dietro il mezzo durante manovra","toccare direttamente oggetti taglienti","sollevare carichi instabili senza ripianificare"]'::jsonb,'["visibilità insufficiente","dispositivo mezzo non funzionante","rifiuto non identificabile o pericoloso"]'::jsonb,'[{"kind":"video_hub","title":"Napo - movimentazione e trasporto","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:polizia-roadside-lab','Tabletop Polizia Locale: controllo stradale sicuro','hybrid','Allenare posizionamento, visibilità, gestione del traffico, comunicazione e de-escalation.','Usare una planimetria, coni/segnaposto o una simulazione in area protetta.','["scegli posizione mezzi e operatori","definisci zona sicura e via di disimpegno","predisponi alta visibilità e segnalazione","simula il contatto","inserisci un evento di escalation","attiva supporto","debriefing"]'::jsonb,'["posizionamento","visibilità","separazione traffico","comunicazione","supporto","via di disimpegno"]'::jsonb,'["operare con le spalle al traffico senza controllo","concentrare tutti gli operatori nello stesso punto","perdere la via di disimpegno"]'::jsonb,'["traffico non controllabile","visibilità insufficiente","escalation non gestibile con le risorse presenti"]'::jsonb,'[{"kind":"video_hub","title":"Napo - sicurezza stradale","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:verde-operational-lab','Pre-use Verde Pubblico: attrezzatura, area, caldo e quota','hybrid','Allenare un pre-start completo prima dell’uso di attrezzature e dell’accesso a quota.','Su attrezzatura spenta e in sicurezza, usare manuale e checklist del modello reale.','["controlla area e presenza utenti","ispeziona attrezzatura senza rimuovere protezioni","verifica DPI e compatibilità","valuta meteo/calore","scegli accesso o protezione per quota","segrega l’area","definisci stop ed emergenza"]'::jsonb,'["area","attrezzatura","protezioni","DPI","calore","quota","emergenza"]'::jsonb,'["avviare macchina con protezioni dubbie","lavorare in quota senza sistema coerente","continuare con stress termico crescente"]'::jsonb,'["protezione danneggiata","utenti nella zona","meteo o calore incompatibile","sistema quota non definito"]'::jsonb,'[{"kind":"video_hub","title":"Napo - manutenzione e attrezzature","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:fondamenti-hierarchy-lab','Laboratorio gerarchia delle misure','digital','Saper passare da “prestare attenzione” a una misura concreta e più efficace.','Partire da tre rischi quotidiani reali o simulati.','["descrivi il pericolo senza usare la parola rischio","identifica chi è esposto","proponi eliminazione o sostituzione","proponi protezione collettiva/tecnica","aggiungi misura organizzativa","usa DPI solo dove resta rischio residuo","definisci chi verifica"]'::jsonb,'["pericolo chiaro","esposti","misura alla fonte","misura collettiva","organizzazione","DPI residuo","verifica"]'::jsonb,'["partire subito dal DPI","confondere regola con misura tecnica","nessun responsabile della verifica"]'::jsonb,'["mancano dati essenziali","rischio grave/immediato"]'::jsonb,'[{"kind":"video_hub","title":"Napo - principi base della prevenzione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false)
on conflict (stable_key) do update set title=excluded.title,lab_type=excluded.lab_type,objective=excluded.objective,briefing=excluded.briefing,steps=excluded.steps,checklist=excluded.checklist,critical_errors=excluded.critical_errors,stop_conditions=excluded.stop_conditions,media=excluded.media,sources=excluded.sources,requires_physical_validation=excluded.requires_physical_validation,active=true,updated_at=now();

with pairs(course_key,scenario_key,lab_key) as (values
('backoffice','v22:backoffice-workstation','v22:backoffice-audit'),
('frontoffice','v22:frontoffice-public','v22:frontoffice-deescalation'),
('ecologici','v22:ecologici-route','v22:ecologici-prestart'),
('polizia','v22:polizia-roadside','v22:polizia-roadside-lab'),
('verde','v22:verde-prestart','v22:verde-operational-lab'),
('fondamenti','v22:fondamenti-control','v22:fondamenti-hierarchy-lab')
)
insert into public.course_scenarios_v22(course_id,scenario_id,position,required,context)
select c.id,s.id,2,true,jsonb_build_object('assigned_by','v22_002','specific',true)
from pairs p join public.courses c on c.stable_key=p.course_key join public.training_scenarios_v22 s on s.stable_key=p.scenario_key
where c.active and coalesce(c.metadata->>'freeze_scope','')=''
on conflict(course_id,scenario_id) do update set position=excluded.position,required=true,context=excluded.context;

with pairs(course_key,scenario_key,lab_key) as (values
('backoffice','v22:backoffice-workstation','v22:backoffice-audit'),
('frontoffice','v22:frontoffice-public','v22:frontoffice-deescalation'),
('ecologici','v22:ecologici-route','v22:ecologici-prestart'),
('polizia','v22:polizia-roadside','v22:polizia-roadside-lab'),
('verde','v22:verde-prestart','v22:verde-operational-lab'),
('fondamenti','v22:fondamenti-control','v22:fondamenti-hierarchy-lab')
)
insert into public.course_practice_labs_v22(course_id,practice_lab_id,position,required,context)
select c.id,l.id,2,true,jsonb_build_object('assigned_by','v22_002','specific',true)
from pairs p join public.courses c on c.stable_key=p.course_key join public.practice_labs_v22 l on l.stable_key=p.lab_key
where c.active and coalesce(c.metadata->>'freeze_scope','')=''
on conflict(course_id,practice_lab_id) do update set position=excluded.position,required=true,context=excluded.context;

with target as (
  select distinct on(c.id) c.stable_key,cv.id course_version_id
  from public.courses c join public.course_versions cv on cv.course_id=c.id
  where c.stable_key in ('backoffice','frontoffice','ecologici','polizia','verde','fondamenti') and c.active and coalesce(c.metadata->>'freeze_scope','')=''
  order by c.id,cv.version_number desc
)
insert into public.course_verification_requirements(course_version_id,requirement_key,title,verification_mode,required,completion_mode,metadata)
select course_version_id,'v22_competency_simulation','Verifica competenze – scenario pratico','simulation',true,'platform_or_external',jsonb_build_object('standard','v22.002','scenario_required',true,'evidence_mode','instructor_or_platform_scenario','didactic_goal','decision_quality','course_key',stable_key)
from target
on conflict(course_version_id,requirement_key) do update set title=excluded.title,verification_mode=excluded.verification_mode,required=true,completion_mode=excluded.completion_mode,metadata=excluded.metadata,updated_at=now();
